"View: Contents
package product

import (
	"context"
	"fmt"

	"github.com/Sokol111/ecommerce-commons/pkg/core/logger"
	"github.com/Sokol111/ecommerce-commons/pkg/kafka/outbox"
	"github.com/Sokol111/ecommerce-commons/pkg/mongo"
	"go.uber.org/zap"
)

type DeleteProductCommand struct {
	ID string
}

type DeleteProductCommandHandler interface {
	Handle(ctx context.Context, cmd DeleteProductCommand) error
}

type deleteProductHandler struct {
	repo         Repository
	outbox       outbox.Outbox
	txManager    mongo.TxManager
	eventFactory ProductEventFactory
}

func NewDeleteProductHandler(
	repo Repository,
	outbox outbox.Outbox,
	txManager mongo.TxManager,
	eventFactory ProductEventFactory,
) DeleteProductCommandHandler {
	return &deleteProductHandler{
		repo:         repo,
		outbox:       outbox,
		txManager:    txManager,
		eventFactory: eventFactory,
	}
}

func (h *deleteProductHandler) Handle(ctx context.Context, cmd DeleteProductCommand) error {
	msg := h.eventFactory.NewProductDeletedOutboxMessage(ctx, cmd.ID)

